/** Brand-safe scene backgrounds and continuous background motion. */
export {
  TOP_TEXT_AREA_RATIO,
  gradientBackground,
  BrandGradientOverlay,
} from "../scene-templates/color-utils";
export * from "../scene-templates/background-effect";

/**
 * Background motion effects for templates.
 *
 * Applied to the background layer (media, gradient) throughout the entire scene.
 * Continuous motion — not tied to text timing.
 *
 * Templates with usesGlobalBackgroundEffect: true consume the video-level default.
 *
 * 9 effects, each with a distinct mood:
 * - static:        No motion — intentional stillness
 * - slow-zoom-in:  Draw attention inward, build focus
 * - slow-zoom-out: Reveal, establish, pull back
 * - ken-burns:     Classic cinematic photo motion (zoom + pan, direction alternates per scene)
 * - drift:         Gentle lateral pan (direction alternates per scene)
 * - pulse:         Beat-synced energy
 * - breathe:       Ambient dreamy float
 * - slow-tilt:     Tension, Dutch angle drift
 * - camera-shake:  Intensity, handheld drama
 */

import { interpolate } from "../motion";

export interface BackgroundTransform {
  transform: string;
  transformOrigin: string;
}

export const BACKGROUND_EFFECTS = [
  "static",
  "slow-zoom-in",
  "slow-zoom-out",
  "ken-burns",
  "drift",
  "pulse",
  "breathe",
  "slow-tilt",
  "camera-shake",
] as const;

// ─── Directional variant helpers ────────────────────────────────
// Ken Burns and Drift have internal direction variants that alternate
// by scene index to create visual variety across a video.

type Direction = "right" | "left" | "up" | "down";
const DIRECTIONS: Direction[] = ["right", "left", "up", "down"];

function getKenBurnsTransform(progress: number, direction: Direction): BackgroundTransform {
  const scale = interpolate(progress, [0, 1], [1.05, 1.15]);
  const mainAxis = direction === "right" || direction === "left";
  const sign = direction === "right" || direction === "down" ? 1 : -1;
  const primary = interpolate(progress, [0, 1], [-2 * sign, 2 * sign]);
  const secondary = interpolate(progress, [0, 1], [-0.5, 0.5]);

  const x = mainAxis ? primary : secondary;
  const y = mainAxis ? secondary : primary;

  return {
    transform: `scale(${scale}) translate(${x}%, ${y}%)`,
    transformOrigin: "center",
  };
}

function getDriftTransform(progress: number, direction: Direction): BackgroundTransform {
  const horizontal = direction === "right" || direction === "left";
  const sign = direction === "right" || direction === "down" ? 1 : -1;
  const offset = interpolate(progress, [0, 1], [-2 * sign, 2 * sign]);

  return {
    transform: horizontal
      ? `scale(1.1) translateX(${offset}%)`
      : `scale(1.1) translateY(${offset}%)`,
    transformOrigin: "center",
  };
}

// ─── Public API ─────────────────────────────────────────────────

/**
 * Get background transform for the current progress.
 *
 * @param effect — background effect name
 * @param progress — scene progress 0→1
 * @param beatIntensity — 0→1 for beat-reactive effects
 * @param sceneIndex — used to alternate direction for ken-burns/drift
 */
export function getBackgroundTransform(
  effect: string | undefined,
  progress: number,
  beatIntensity = 0,
  sceneIndex = 0,
): BackgroundTransform {
  const dir = DIRECTIONS[sceneIndex % DIRECTIONS.length];

  // Camera motion is opt-in. In particular, a scene-relative zoom restarts
  // at every cut and can look like the incoming media snaps backwards.
  // Footage already contains motion, while photo scenes that benefit from a
  // Ken Burns treatment can request one explicitly.
  const resolved = effect ?? "static";

  switch (resolved) {
    case "slow-zoom-in":
      return {
        transform: `scale(${interpolate(progress, [0, 1], [1, 1.12])})`,
        transformOrigin: "center",
      };

    case "slow-zoom-out":
      return {
        transform: `scale(${interpolate(progress, [0, 1], [1.12, 1])})`,
        transformOrigin: "center",
      };

    case "ken-burns":
      return getKenBurnsTransform(progress, dir);

    case "drift":
      return getDriftTransform(progress, dir);

    case "pulse": {
      // Subtle scale pulse synced to beat
      const base = 1 + beatIntensity * 0.04;
      const breathe = 1 + Math.sin(progress * Math.PI * 2) * 0.02;
      return {
        transform: `scale(${base * breathe})`,
        transformOrigin: "center",
      };
    }

    case "breathe": {
      // Slow ambient float — gentle scale + vertical drift, not beat-synced
      const s = 1 + Math.sin(progress * Math.PI) * 0.03;
      const y = Math.sin(progress * Math.PI) * 0.5;
      return {
        transform: `scale(${s}) translateY(${y}%)`,
        transformOrigin: "center",
      };
    }

    case "slow-tilt": {
      // Subtle Dutch angle drift
      const angle = interpolate(progress, [0, 1], [0, 2.5]);
      return {
        transform: `scale(1.08) rotate(${angle}deg)`,
        transformOrigin: "center",
      };
    }

    case "camera-shake": {
      // Rapid small offsets for handheld/dramatic feel
      // Deterministic noise based on progress for reproducibility
      const t = progress * 40;
      const sx = Math.sin(t * 2.3) * 0.4 + Math.sin(t * 5.7) * 0.2;
      const sy = Math.cos(t * 3.1) * 0.3 + Math.cos(t * 4.9) * 0.15;
      const sr = Math.sin(t * 1.7) * 0.3;
      return {
        transform: `scale(1.05) translate(${sx}%, ${sy}%) rotate(${sr}deg)`,
        transformOrigin: "center",
      };
    }

    case "static":
    default:
      return {
        transform: "none",
        transformOrigin: "center",
      };
  }
}

import React from "react";

// Source-owned templates may live in a consumer's tree while VideoFrame comes
// from the package. Both copies must observe the same internal context or the
// consumer template would mount a second video over the player-owned plane,
// and would never inherit the player's native media audio state.
export type ExternalVideoBackdropMode = false | "pending" | "ready" | "fallback";

export type MediaRecoveryReason = "decode-error" | "frame-readiness-timeout" | "stalled-media" | "playback-error";

interface BackdropContextValue {
  mode: ExternalVideoBackdropMode;
  audioMuted: boolean;
  audioVolume: number;
  preparingNarration?: boolean;
  onMediaError?: (reason?: MediaRecoveryReason) => void;
}

const DEFAULT: BackdropContextValue = { mode: false, audioMuted: true, audioVolume: 1 };

const sharedContext = globalThis as typeof globalThis & {
  __vanillaskyVideoBackdropContext?: React.Context<BackdropContextValue>;
};
const BackdropContext = sharedContext.__vanillaskyVideoBackdropContext
  ??= React.createContext<BackdropContextValue>(DEFAULT);

export function ExternalVideoBackdropProvider({
  mode,
  audioMuted = true,
  audioVolume = 1,
  preparingNarration = false,
  onMediaError,
  children,
}: {
  mode: ExternalVideoBackdropMode;
  audioMuted?: boolean;
  audioVolume?: number;
  preparingNarration?: boolean;
  onMediaError?: (reason?: MediaRecoveryReason) => void;
  children: React.ReactNode;
}) {
  const value = React.useMemo(
    () => ({ mode, audioMuted, audioVolume, preparingNarration, onMediaError }),
    [mode, audioMuted, audioVolume, preparingNarration, onMediaError],
  );
  return (
    <BackdropContext.Provider value={value}>
      {children}
    </BackdropContext.Provider>
  );
}

export function useExternalVideoBackdrop(): ExternalVideoBackdropMode {
  return React.useContext(BackdropContext).mode;
}

export function useMediaAudio(): { muted: boolean; volume: number } {
  const { audioMuted, audioVolume } = React.useContext(BackdropContext);
  return { muted: audioMuted, volume: audioVolume };
}

/** Internal first-frame priming state; an explicit viewer pause never sets it. */
export function useNarrationPreroll(): boolean {
  return React.useContext(BackdropContext).preparingNarration === true;
}

/** Routes local decoder/playback failures to the scene-owned recovery surface. */
export function useMediaFailure(): ((reason?: MediaRecoveryReason) => void) | undefined {
  return React.useContext(BackdropContext).onMediaError;
}

export type MediaPosition = "center" | "top" | "bottom" | "left" | "right";

const MEDIA_POSITIONS: Record<MediaPosition, string> = {
  center: "center center",
  top: "center top",
  bottom: "center bottom",
  left: "left center",
  right: "right center",
};

export function resolveMediaPosition(value: string): string {
  return MEDIA_POSITIONS[value as MediaPosition] ?? MEDIA_POSITIONS.center;
}

import React, { useCallback, useEffect, useRef, useState } from "react";
import { getBackgroundTransform } from "../backgrounds";
import { type MediaRecoveryReason, useMediaAudio, useMediaFailure, useNarrationPreroll } from "./external-video-backdrop";
import { resolveMediaPosition } from "./media-position";

export interface SceneVideoBackdropProps {
  mediaUrl: string;
  mediaPoster?: string;
  mediaPosition?: string;
  backgroundEffect?: string;
  progress: number;
  /** Narration-led visible duration; muted or pitch-preserving footage may be gently retimed. */
  sceneDuration?: number;
  /** Internal player-owned decoder priming, distinct from viewer pause. */
  preparingNarration?: boolean;
  beatIntensity?: number;
  isPlaying: boolean;
  muted?: boolean;
  volume?: number;
  playbackId?: string;
  onReady?: () => void;
  onError?: () => void;
}

export const SceneVideoBackdrop: React.FC<SceneVideoBackdropProps> = ({
  mediaUrl,
  mediaPoster,
  mediaPosition = "center",
  backgroundEffect,
  progress,
  sceneDuration,
  preparingNarration = false,
  beatIntensity = 0,
  isPlaying,
  muted,
  volume,
  playbackId = mediaUrl,
  onReady,
  onError,
}) => {
  const inheritedAudio = useMediaAudio();
  const reportMediaFailure = useMediaFailure();
  const inheritedPreroll = useNarrationPreroll();
  const rewindPreroll = preparingNarration || inheritedPreroll;
  const resolvedMuted = muted ?? inheritedAudio.muted;
  const resolvedVolume = volume ?? inheritedAudio.volume;
  const resolvedPosition = resolveMediaPosition(mediaPosition);
  const bgTransform = getBackgroundTransform(backgroundEffect, progress, beatIntensity);
  const [decodedVideoUrl, setDecodedVideoUrl] = useState<string>();
  const [waitingKey, setWaitingKey] = useState<string>();
  const [exhaustedKey, setExhaustedKey] = useState<string>();

  const videoRef = useRef<HTMLVideoElement>(null);
  const playableVideoUrl = useRef<string | undefined>(undefined);
  const startedVideoUrl = useRef<string | undefined>(undefined);
  const startedPlaybackId = useRef<string | undefined>(undefined);
  const videoPresentationKey = `${playbackId}\0${mediaUrl}`;

  const presentationRef = useRef({ key: videoPresentationKey, playing: isPlaying });
  presentationRef.current = { key: videoPresentationKey, playing: isPlaying };
  const unavailable = (reason: MediaRecoveryReason = "playback-error") => {
    if (presentationRef.current.key === videoPresentationKey && presentationRef.current.playing) {
      setExhaustedKey(videoPresentationKey);
      onError?.();
      reportMediaFailure?.(reason);
    }
  };
  useEffect(() => {
    // Hidden preparation is bounded by mounted readiness once its cut is due.
    // It must not spend the next scene's stall deadline while still incoming.
    if (!isPlaying || rewindPreroll || waitingKey !== videoPresentationKey) {
      if (waitingKey) setWaitingKey(undefined);
      return;
    }
    const video = videoRef.current;
    if (!video) return;
    const expectedSource = video.getAttribute("src") === mediaUrl ? video.src : undefined;
    let awaitingPlayback = playableVideoUrl.current !== mediaUrl || video.currentSrc !== expectedSource;
    let previousTime = video.currentTime;
    let forwardFrames = 0;
    let stopped = false;
    let frame: number | undefined;
    let poll: ReturnType<typeof setTimeout> | undefined;
    const observe = (_now?: number, metadata?: VideoFrameCallbackMetadata) => {
      if (stopped) return;
      const currentSource = video.currentSrc === expectedSource;
      if (currentSource && awaitingPlayback && video.readyState >= HTMLMediaElement.HAVE_FUTURE_DATA) {
        playableVideoUrl.current = mediaUrl;
        awaitingPlayback = false;
        clearTimeout(deadline);
        deadline = setTimeout(fail, 1000);
      }
      const time = metadata?.mediaTime ?? video.currentTime;
      if (!currentSource || video.seeking || time < previousTime) forwardFrames = 0;
      else if (time > previousTime + .001) forwardFrames++;
      previousTime = time;
      // One seek frame is not resumed motion. Require consecutive forward
      // observations before releasing the original bounded stall deadline.
      if (forwardFrames >= 2) {
        playableVideoUrl.current = mediaUrl;
        stopped = true;
        clearTimeout(deadline);
        setWaitingKey(undefined);
        return;
      }
      if (video.requestVideoFrameCallback) frame = video.requestVideoFrameCallback(observe);
      else poll = setTimeout(observe, 50);
    };
    // A seek can emit waiting without another playing event, even while frames
    // resume. Keep the decoder visible and observe motion directly. A real
    // stall gets the player's authored chapter instead of an endless spinner.
    const fail = () => { if (!stopped) { stopped = true; unavailable(awaitingPlayback ? "frame-readiness-timeout" : "stalled-media"); } };
    // Initial network/decode work has the same bound as mounted readiness.
    // A decoded still with no future data is still cold, even after its first
    // frame callback. Keep the short bound only after playback was available.
    let deadline = setTimeout(fail, awaitingPlayback ? 8000 : 1000);
    observe();
    return () => {
      stopped = true;
      clearTimeout(deadline);
      clearTimeout(poll);
      if (frame !== undefined) video.cancelVideoFrameCallback?.(frame);
    };
  }, [waitingKey, videoPresentationKey, isPlaying, rewindPreroll]);

  const onReadyRef = useRef(onReady);
  onReadyRef.current = onReady;
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    let stopped = false;
    let frame: number | undefined;
    const markPresented = () => {
      if (stopped || !video.isConnected || presentationRef.current.key !== videoPresentationKey
        || video.getAttribute("src") !== mediaUrl || video.currentSrc !== video.src) return false;
      if (video.readyState >= HTMLMediaElement.HAVE_FUTURE_DATA) playableVideoUrl.current = mediaUrl;
      video.dispatchEvent(new Event("vanillasky:video-frame-presented", { bubbles: true }));
      onReadyRef.current?.();
      setDecodedVideoUrl(mediaUrl);
      stopped = true;
      return true;
    };
    const observe = () => {
      if (stopped || frame !== undefined) return;
      if (video.requestVideoFrameCallback) {
        frame = video.requestVideoFrameCallback(() => {
          frame = undefined;
          if (!markPresented()) observe();
        });
      } else if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) markPresented();
    };
    // A cached resource can finish loading while its Suspense tree is still
    // detached. Observe the mounted frame even if loadeddata was missed.
    video.addEventListener("loadeddata", observe);
    observe();
    return () => {
      stopped = true;
      video.removeEventListener("loadeddata", observe);
      if (frame !== undefined) video.cancelVideoFrameCallback?.(frame);
    };
  }, [mediaUrl, videoPresentationKey]);

  const fitDuration = useCallback((video: HTMLVideoElement) => {
    // Allow a small decode-to-speech onset margin without changing narration.
    video.playbackRate = (resolvedMuted || video.preservesPitch === true) && sceneDuration && Number.isFinite(video.duration) && video.duration > 0
      ? Math.max(.75, Math.min(1, video.duration / (sceneDuration + .2))) : 1;
  }, [resolvedMuted, sceneDuration]);
  useEffect(() => {
    if (videoRef.current) fitDuration(videoRef.current);
  }, [fitDuration]);
  const continueMotion = (video: HTMLVideoElement) => {
    if (!isPlaying) return;
    // The finite scene clock bounds silent coverage. Speech may outlast a
    // short clip; repeat motion until the scene ends, never audible dialogue.
    if (!resolvedMuted) {
      unavailable();
      return;
    }
    video.currentTime = 0;
    void video.play().catch(() => unavailable());
  };

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    // React Strict Mode rehearses setup → cleanup → setup in development.
    // The cleanup deliberately releases the decoder, so the repeated setup
    // must restore the declarative source before the playback effect runs.
    if (video.getAttribute("src") !== mediaUrl) {
      video.setAttribute("src", mediaUrl);
      video.load();
    }
  }, [mediaUrl]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    // A source change already starts a native load via React's src update.
    // Tear down the decoder only on unmount, never cancel that new request.
    return () => {
      video.pause();
      video.removeAttribute("src");
      video.load();
      startedVideoUrl.current = undefined;
      startedPlaybackId.current = undefined;
    };
  }, []);

  useEffect(() => {
    const video = videoRef.current;
    if (video) video.volume = resolvedVolume;
  }, [resolvedVolume]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (!isPlaying) {
      video.pause();
      if (rewindPreroll && video.currentTime > 0) video.currentTime = 0;
      return;
    }
    if (startedPlaybackId.current === playbackId) {
      if (video.ended) continueMotion(video);
      else void video.play().catch(() => unavailable());
      return;
    }
    const changingSource = startedVideoUrl.current !== undefined && startedVideoUrl.current !== mediaUrl;
    fitDuration(video);
    if (!changingSource && video.currentTime > 0) video.currentTime = 0;
    video.play().catch(() => unavailable());
    startedVideoUrl.current = mediaUrl;
    startedPlaybackId.current = playbackId;
  }, [isPlaying, mediaUrl, playbackId, rewindPreroll]);

  const enforceRequestedPause = (event: React.SyntheticEvent<HTMLVideoElement>) => {
    // WebKit may enter playback without a playing event while seeking or
    // waiting. Both native start events must honor the latest requested hold.
    if (presentationRef.current.playing) return;
    event.currentTarget.pause();
    if (rewindPreroll && event.currentTarget.currentTime > 0) event.currentTarget.currentTime = 0;
  };

  const mediaStyle: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    objectFit: "cover",
    objectPosition: resolvedPosition,
    transform: bgTransform.transform,
    transformOrigin: bgTransform.transformOrigin,
  };
  return (
    <>
      {exhaustedKey === videoPresentationKey && <div
        role="status" data-media-continuity="exhausted"
        style={{ position: "absolute", inset: 0, zIndex: 3, background: "#000", color: "#bbb", display: "grid", placeContent: "center", font: "14px system-ui" }}
      >Visual unavailable</div>}
      <video
        ref={videoRef}
        src={mediaUrl}
        poster={decodedVideoUrl !== mediaUrl ? mediaPoster || undefined : undefined}
        muted={resolvedMuted}
        // Let the decoder repeat without an ended → script seek/play round trip.
        // The finite scene clock still owns pause and disposal; never loop speech.
        loop={resolvedMuted && isPlaying && Number.isFinite(sceneDuration) && Number(sceneDuration) > 0}
        playsInline
        preload="auto"
        onLoadedMetadata={event => fitDuration(event.currentTarget)}
        onEnded={event => continueMotion(event.currentTarget)}
        onPlay={enforceRequestedPause}
        onPlaying={event => {
          if (event.currentTarget.currentSrc === event.currentTarget.src
            && event.currentTarget.getAttribute("src") === mediaUrl
            && event.currentTarget.readyState >= HTMLMediaElement.HAVE_FUTURE_DATA) playableVideoUrl.current = mediaUrl;
          enforceRequestedPause(event);
        }}
        onWaiting={() => { if (isPlaying) setWaitingKey(videoPresentationKey); }}
        onError={onError}
        data-media-position={mediaPosition}
        data-video-backdrop="scene"
        style={{ ...mediaStyle, visibility: exhaustedKey === videoPresentationKey ? "hidden" : undefined }}
      />
    </>
  );
};

/**
 * Color utilities for scene templates.
 *
 * Provides safe color manipulation that works with hex colors
 * and graceful fallbacks for non-hex inputs.
 */
import React from "react";
import { resolveTokens, darken, orderDarkToLight, type BackgroundFamily } from "../theme";

// ─── Layout constants ───────────────────────────────────────
//
// Shared vertical layout for templates that place a TextOverlay at the top of
// the scene (showcase-*, chart-*, infographic-*). Using a single constant
// guarantees the headline sits in the same place across every template, so
// scene-to-scene cuts don't visually jump.
//
// TextOverlay vertically centers itself inside its container, so the visual
// midline of the headline = TOP_TEXT_AREA_RATIO / 2 of the scene height.
export const TOP_TEXT_AREA_RATIO = 0.32;

/**
 * Gradient background — clean 2-color linear gradient with a subtle
 * animated breathing overlay. Matches the look of a plain CSS
 * `linear-gradient(90deg, colorA, colorB)` so palette chips preview
 * exactly what templates render.
 *
 * The animation is deliberately minimal: two low-opacity radial blobs
 * of the same two colors drift slowly, adding just enough motion for
 * video without introducing a third "midtone" color that muddies
 * the gradient (a common source of unwanted purple/brown tints).
 */
export function gradientBackground({
  colorA,
  colorB,
  solidBg,
  progress,
  sceneDuration,
  seed,
  family,
}: {
  colorA: string;
  colorB: string;
  /**
   * When set, the function returns this color as a solid background
   * (no gradient, no animated radial overlays). Used when the user has
   * a scraped brand whose darkest color reads as a real surface — the
   * accent stays on text/CTAs, but the bg goes flat instead of pairing
   * with an unrelated brand color and producing a noisy gradient.
   */
  solidBg?: string;
  progress: number;
  sceneDuration?: number;
  seed: number;
  /**
   * Background family from the style preset. Omitted = "mesh", the original
   * look — so existing configs are untouched. All families are pure CSS
   * background strings (no `filter`, which the SVG export can't rasterize)
   * and stay deterministic in `progress`.
   */
  family?: BackgroundFamily;
}): string {
  if (solidBg) return solidBg;
  // Every scene owns its foreground motion clock, but consecutive scenes that
  // use the same brand backdrop must not visibly reset that backdrop. Run one
  // eased closed loop per scene: the gradient has zero velocity and the exact
  // same pixels at progress 0 and 1, regardless of scene duration or content
  // seed. Seeded variation is strongest mid-scene and converges to zero at
  // both handoff edges.
  const normalizedProgress = Math.max(0, Math.min(1, progress));
  const atBoundary = normalizedProgress === 0 || normalizedProgress === 1;
  const easedLoop = normalizedProgress * normalizedProgress * (3 - 2 * normalizedProgress);
  const seedEnvelope = atBoundary ? 0 : Math.sin(normalizedProgress * Math.PI) ** 2;
  void sceneDuration;

  const seededRandom = (s: number): number => {
    const x = Math.sin(s * 12.9898 + s * 78.233) * 43758.5453;
    return x - Math.floor(x);
  };
  const phase = seededRandom(seed) * Math.PI * 2 * seedEnvelope;
  const t = (atBoundary ? 0 : easedLoop * Math.PI * 2) + phase;

  // Darker of the two colors anchors the top of the frame so text and logos
  // sit over the stronger value. 180deg = top→bottom.
  const [topColor, bottomColor] = orderDarkToLight(colorA, colorB);

  if (family === "wash") {
    // No radials: one calm vertical ramp that drifts a few percent over the
    // scene. Reads considered rather than energetic.
    const shift = Math.sin(t) * 6;
    return `linear-gradient(${175 + shift}deg, ${topColor} 0%, ${bottomColor} 100%)`;
  }

  if (family === "spotlight") {
    // A single hard pool of accent high in the frame over a near-black
    // surround — high contrast, very little colour area.
    const x = 50 + Math.sin(t) * 8;
    const y = 28 + Math.cos(t + 1) * 5;
    return `
      radial-gradient(ellipse 70% 55% at ${x}% ${y}%, ${colorA}66 0%, ${colorA}1a 45%, transparent 72%),
      linear-gradient(180deg, ${darken(topColor, 0.55)} 0%, ${darken(bottomColor, 0.7)} 100%)
    `;
  }

  const x1 = 25 + Math.sin(t) * 25;
  const y1 = 30 + Math.cos(t + 1.0) * 25;
  const x2 = 75 + Math.sin(t + 2.0) * 25;
  const y2 = 70 + Math.cos(t + 3.5) * 25;

  return `
    radial-gradient(ellipse 60% 60% at ${x1}% ${y1}%, ${colorA}4d 0%, transparent 65%),
    radial-gradient(ellipse 60% 60% at ${x2}% ${y2}%, ${colorB}4d 0%, transparent 65%),
    linear-gradient(180deg, ${topColor} 0%, ${bottomColor} 100%)
  `;
}

/**
 * Animated brand-background overlay. Foreground semantic colours never alter
 * this visual background.
 */
export const BrandGradientOverlay: React.FC<{
  style: Parameters<typeof resolveTokens>[0];
  progress: number;
  sceneDuration?: number;
  seed: number;
}> = ({ style: globalStyle, progress, sceneDuration, seed }) => {
  const tokens = resolveTokens(globalStyle);
  const [first, second] = tokens.background.type === "gradient"
    ? tokens.background.colors
    : [tokens.background.color, tokens.background.color];
  const solidBg = tokens.background.type === "solid" ? tokens.background.color : undefined;

  return React.createElement("div", {
    "data-brand-gradient": "true",
    style: {
      position: "absolute" as const,
      inset: 0,
      background: gradientBackground({ colorA: first, colorB: second, solidBg, progress, sceneDuration, seed, family: tokens.preset.background }),
      pointerEvents: "none" as const,
    },
  });
};
